root=Path.home()/'fiber-web-export';folder=root/'browser/scenes/grasp';cfg=json.loads((folder/'scene.json').read_text());m=mujoco.MjModel.from_xml_path(str(folder/cfg.get('xml','scene.xml')));d=mujoco.MjData(m);d.qpos[:]=cfg['qpos'];d.qvel[:]=0;d.mocap_pos[:]=np.array(cfg['mocap_pos']).reshape(-1,3);d.mocap_quat[:]=np.array(cfg['mocap_quat']).reshape(-1,4);d.qpos[:3]=[0,.72,.8];d.qpos[3:7]=[2**-.5,0,0,-2**-.5];d.qpos[cfg['qadr']]=cfg['default_q'];d.qpos[cfg['hand']['qadr']]=0;d.qpos[cfg['qadr'][18]]=1.4;d.qpos[cfg['qadr'][25]]=1.4;mujoco.mj_forward(m,d);bfm=load_bfm(str(root/'models/model_best_emd.pt'),device='cpu',control_profile='bfm05_xl',verbose=False);obs={'state':torch.tensor(np.r_[d.qpos[cfg['qadr']]-cfg['default_q'],np.zeros(29),[0,0,-1],np.zeros(3)][None],dtype=torch.float32),'last_action':torch.zeros(1,29),'history_actor':torch.zeros(1,837)};shim=BFMMuJoCoSim.__new__(BFMMuJoCoSim);shim.model=m;shim.data=d;shim._mj=mujoco;shim._body_ids=[mujoco.mj_name2id(m,mujoco.mjtObj.mjOBJ_BODY,n) for n in KEYPOINT_NAMES[:-1]];shim._body_ids_arr=np.array(shim._body_ids);obs['privileged_state']=torch.tensor(shim.get_privileged_state()[None]);cfg.update(qpos=d.qpos.tolist(),qvel=d.qvel.tolist(),anchor=bfm_backward_anchor(bfm,obs)[0].tolist(),initial_obs={k:v[0].tolist() for k,v in obs.items()},provenance={**cfg['provenance'],'start':'neutral standing, arms resting down with relaxed elbows, open fingers; no pre-grasp pose','start_frame':None});(folder/'scene.json').write_text(json.dumps(cfg,separators=(',',':')));print('NEUTRAL GRASP START EXPORTED')
